import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group } = ctx.THREE;

  const group = new Group();
  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create plane geometry (512x320 in atlas, normalized to scene units)
  // Maintain 512:320 aspect ratio; scale to reasonable scene size
  const aspectRatio = 512 / 320; // 1.6
  const planeWidth = 1.6;
  const planeHeight = 1.0;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // Load brushed metal texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create material with texture node
  const material = new MeshBasicNodeMaterial();

  // Set up UV coordinates for atlas region (0, 0, 512, 320 in a larger atlas)
  // Assuming a power-of-2 atlas; map the rect to normalized UV space
  const uvNode = uv();
  const atlasUVNode = mix(
    uvNode.mul(1.0), // Full plane uses the atlas rect
    uvNode,
    0.0 // No blending; direct passthrough
  );

  material.colorNode = texture(
    atlasUVNode
  );

  // Placeholder until texture loads; then bind real texture
  texturePromise.then((tex) => {
    // Clamp texture to atlas region boundaries
    tex.repeat.set(1.0, 1.0);
    tex.offset.set(0.0, 0.0);
    material.colorNode = texture(tex, atlasUVNode);
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // userData cleanup hook
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (mesh.material.map) {
      mesh.material.map.dispose();
    }
  };

  return group;
}
